const b64 = (bytes: Uint8Array | number[]): string => Buffer.from(Uint8Array.from(bytes)).toString("base64");
const asc = (s: string): number[] => Array.from(s, (c) => c.charCodeAt(0));

function crc32(bytes: number[]): number {
  let c = 0xffffffff;
  for (const x of bytes) {
    c ^= x;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  }
  return (c ^ 0xffffffff) >>> 0;
}
const be32 = (n: number): number[] => [(n >>> 24) & 0xff, (n >>> 16) & 0xff, (n >>> 8) & 0xff, n & 0xff];
const le32 = (n: number): number[] => [n & 0xff, (n >>> 8) & 0xff, (n >>> 16) & 0xff, (n >>> 24) & 0xff];
function chunk(type: string, data: number[]): number[] {
  const td = [...asc(type), ...data];
  return [...be32(data.length), ...td, ...be32(crc32(td))];
}

/**
 * 96 pseudo-random bytes carried by every test image. Their base64 is high
 * entropy, so the entropy layer masks a payload that is NOT exempt; without
 * them a small image is low-entropy text that no layer masks, and a "masked"
 * or "passes" assertion would prove nothing.
 */
const RAND: number[] = (() => {
  const out: number[] = [];
  let x = 0x2545f491;
  for (let i = 0; i < 96; i++) {
    x ^= x << 13; x >>>= 0; x ^= x >>> 17; x ^= x << 5; x >>>= 0;
    out.push(x & 0xff);
  }
  return out;
})();

/** A structurally valid PNG: IHDR, a private chunk of RAND, optional tEXt, IDAT, IEND. */
function png(text?: string): number[] {
  const ihdr = chunk("IHDR", [...be32(1), ...be32(1), 8, 2, 0, 0, 0]);
  const rnd = chunk("ruSt", RAND);
  // One RGB pixel row: filter byte 0, then R G B, compressed by Node's own zlib.
  const idat = chunk("IDAT", Array.from(deflateSync(Buffer.from([0, 220, 30, 30]))));
  const txt = text === undefined ? [] : chunk("tEXt", [...asc("Comment"), 0, ...asc(text)]);
  return [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, ...ihdr, ...rnd, ...txt, ...idat, ...chunk("IEND", [])];
}

const here = dirname(fileURLToPath(import.meta.url));
const fixture = (name: string): number[] => Array.from(readFileSync(join(here, "fixtures", name)));

/** A real JPEG (macOS sips), with an APP1 segment of RAND inserted after SOI. */
const JPEG = (() => {
  const real = fixture("real.jpg");
  const app1 = [0xff, 0xe1, ((RAND.length + 2) >> 8) & 0xff, (RAND.length + 2) & 0xff, ...RAND];
  return [...real.slice(0, 2), ...app1, ...real.slice(2)];
})();

/** A real GIF (macOS sips) with a comment extension of RAND before the trailer. */
const GIF = (() => {
  const base = fixture("real.gif");
  return b64([...base.slice(0, -1), 0x21, 0xfe, RAND.length, ...RAND, 0x00, 0x3b]);
})();

/** A real WebP (cwebp) with an EXIF chunk of RAND appended and the RIFF size fixed. */
function withRandChunk(real: number[]): number[] {
  const body = [...real.slice(12), ...asc("EXIF"), ...le32(RAND.length), ...RAND];
  return [...asc("RIFF"), ...le32(body.length + 4), ...asc("WEBP"), ...body];
}
const WEBP_LOSSY = withRandChunk(fixture("real-lossy.webp"));
const WEBP_LOSSLESS = withRandChunk(fixture("real-lossless.webp"));
