// ---- 2. structural context --------------------------------------------------------------------------

describe("the exemption applies only at a real image block at the top of the tool output", () => {
  const data = b64(png());

  test("a Read-shaped file nested inside a structured result is masked", async () => {
    const out = await run({ stdout: "x", meta: readShape(data) });
    expect(out.text).not.toContain(data);
  });

  test("a bare { base64, type } object without the image block is masked", async () => {
    const out = await run({ base64: data, type: "image/png" });
    expect(out.text).not.toContain(data);
  });

  test("a text block that carries a file look-alike is masked", async () => {
    const out = await run({ type: "text", file: { base64: data, type: "image/png" } });
    expect(out.text).not.toContain(data);
  });

  test("an API source block outside an image block is masked", async () => {
    const out = await run([{ type: "document", source: { type: "base64", media_type: "image/png", data } }]);
    expect(out.text).not.toContain(data);
  });

  test("an image block in the output's content array passes", async () => {
    const out = await run({ content: [{ type: "image", source: { type: "base64", media_type: "image/png", data } }] });
    expect(out.text).toContain(data);
  });

  test("an image block two levels down is masked", async () => {
    const out = await run({ content: [{ items: [readShape(data)] }] });
    expect(out.text).not.toContain(data);
  });
});

// ---- 3. allowlist without inherited keys ------------------------------------------------------------

describe("the media allowlist has no inherited keys", () => {
  const data = b64(png());

  test.each(["constructor", "toString", "__proto__", "hasOwnProperty", "valueOf", "image/svg+xml", "application/pdf"])(
    "media type %s is masked",
    async (type) => {
      expect((await run(readShape(data, type))).text).not.toContain(data);
      expect((await run(apiShape(data, type))).text).not.toContain(data);
    },
  );

  test("validImage refuses inherited names directly", () => {
    for (const name of ["constructor", "toString", "__proto__"]) {
      expect(validImage(name, data)).toBeNull();
    }
  });

  test("the allowlist is a Map of exactly three image types (WebP is off)", () => {
    expect(MEDIA_VALIDATORS instanceof Map).toBe(true);
    expect([...MEDIA_VALIDATORS.keys()].sort()).toEqual(["image/gif", "image/jpeg", "image/png"]);
  });
});
